    47  int lwan_parse_rfc_time(const char in[static 30], time_t *out)
    48  {
    49      /* This function is used instead of strptime() because locale
    50       * information can affect the parsing.  Instead of defining
    51       * the locale to "C", use hardcoded constants. */
    52      struct tm tm;
    53      const char *str = in;
    54
    55      STRING_SWITCH(str) {
    56      case MULTICHAR_CONSTANT('S','u','n',','): tm.tm_wday = 0; break;
    57      case MULTICHAR_CONSTANT('M','o','n',','): tm.tm_wday = 1; break;
    58      case MULTICHAR_CONSTANT('T','u','e',','): tm.tm_wday = 2; break;
    59      case MULTICHAR_CONSTANT('W','e','d',','): tm.tm_wday = 3; break;
    60      case MULTICHAR_CONSTANT('T','h','u',','): tm.tm_wday = 4; break;
    61      case MULTICHAR_CONSTANT('F','r','i',','): tm.tm_wday = 5; break;
    62      case MULTICHAR_CONSTANT('S','a','t',','): tm.tm_wday = 6; break;
    63      default: return -EINVAL;
    64      }
    65      str += 5;
    66
    67      tm.tm_mday = parse_2_digit_num(str, ' ', 1, 31);
    68      if (UNLIKELY(tm.tm_mday < 0))
    69          return -EINVAL;
    70      str += 3;
    71
    72      STRING_SWITCH(str) {
    73      case MULTICHAR_CONSTANT('J','a','n',' '): tm.tm_mon = 0; break;
    74      case MULTICHAR_CONSTANT('F','e','b',' '): tm.tm_mon = 1; break;
    75      case MULTICHAR_CONSTANT('M','a','r',' '): tm.tm_mon = 2; break;
    76      case MULTICHAR_CONSTANT('A','p','r',' '): tm.tm_mon = 3; break;
    77      case MULTICHAR_CONSTANT('M','a','y',' '): tm.tm_mon = 4; break;
    78      case MULTICHAR_CONSTANT('J','u','n',' '): tm.tm_mon = 5; break;
    79      case MULTICHAR_CONSTANT('J','u','l',' '): tm.tm_mon = 6; break;
    80      case MULTICHAR_CONSTANT('A','u','g',' '): tm.tm_mon = 7; break;
    81      case MULTICHAR_CONSTANT('S','e','p',' '): tm.tm_mon = 8; break;
    82      case MULTICHAR_CONSTANT('O','c','t',' '): tm.tm_mon = 9; break;
    83      case MULTICHAR_CONSTANT('N','o','v',' '): tm.tm_mon = 10; break;
    84      case MULTICHAR_CONSTANT('D','e','c',' '): tm.tm_mon = 11; break;
    85      default: return -EINVAL;
    86      }
    87      str += 4;
    88
    89      tm.tm_year = parse_int(strndupa(str, 4), -1);
    90      if (UNLIKELY(tm.tm_year < 0))
    91          return -EINVAL;
    92      tm.tm_year -= 1900;
    93      if (UNLIKELY(tm.tm_year < 0 || tm.tm_year > 1000))
    94          return -EINVAL;
    95      str += 5;
    96
    97      tm.tm_hour = parse_2_digit_num(str, ':', 0, 23);
    98      str += 3;
    99      tm.tm_min = parse_2_digit_num(str, ':', 0, 59);
   100      str += 3;
   101      tm.tm_sec = parse_2_digit_num(str, ' ', 0, 59);
   102      str += 3;
   103
   104      STRING_SWITCH(str) {
   105      case MULTICHAR_CONSTANT('G','M','T','\0'):
   106          tm.tm_isdst = -1;
   107
   108          *out = timegm(&tm);
   109
   110          if (UNLIKELY(*out == (time_t)-1))
   111              return -EINVAL;
   112
   113          return 0;
   114
   115      default:
   116          return -EINVAL;
   117      }
   118  }
