   120  int lwan_format_rfc_time(const time_t in, char out[static 30])
   121  {
   122      static const char *weekdays = "SunMonTueWedThuFriSat";
   123      static const char *months = "JanFebMarAprMayJunJulAugSepOctNovDec";
   124      const char *weekday, *month;
   125      struct tm tm;
   126      int r;
   127
   128      if (UNLIKELY(!gmtime_r(&in, &tm)))
   129          return -errno;
   130
   131      weekday = weekdays + tm.tm_wday * 3;
   132      month = months + tm.tm_mon * 3;
   133
   134      r = snprintf(out, 30, "%.3s, %02d %.3s %04d %02d:%02d:%02d GMT", weekday,
   135                   tm.tm_mday, month, tm.tm_year + 1900, tm.tm_hour, tm.tm_min,
   136                   tm.tm_sec);
   137      if (UNLIKELY(r < 0 || r > 30))
   138          return -EINVAL;
   139
   140      return 0;
   141  }

