#define HEADER(hdr)                                                            \
    ({                                                                         \
        if (UNLIKELY(end - sizeof(hdr) + 1 < p))                               \
            continue;                                                          \
        p += sizeof(hdr) - 1;                                                  \
        if (UNLIKELY(string_as_int16(p) !=                                     \
                     MULTICHAR_CONSTANT_SMALL(':', ' ')))                      \
            continue;                                                          \
